const DB_PATH = process.env.CONFIG_PATH || path.join(__dirname, "config.json");
let db = { guilds: {}, afk: {} };
try { db = JSON.parse(fs.readFileSync(DB_PATH, "utf8")); }
catch (e) {
  // keep a copy of an unreadable config instead of silently overwriting it
  if (e.code !== "ENOENT") { try { fs.copyFileSync(DB_PATH, DB_PATH + ".corrupt"); } catch {} console.error("[db] unreadable config, started fresh:", e.message); }
}
if (!db || typeof db !== "object") db = { guilds: {}, afk: {} };
db.guilds ||= {};
db.afk ||= {};
let dirty = false;
const save = () => { dirty = true; };
function flush() {
  if (!dirty) return;
  dirty = false;
  try {
    fs.writeFileSync(DB_PATH + ".tmp", JSON.stringify(db, null, 2));
    fs.renameSync(DB_PATH + ".tmp", DB_PATH);
  } catch (e) { console.error("[save]", e.message); }
}
setInterval(flush, 5000);
for (const sig of ["SIGTERM", "SIGINT"]) process.on(sig, () => { flush(); process.exit(0); });

const DEFAULTS = () => ({
  prefix: ",", modlog: null, immuneRoles: [], dmOnAction: true, requireReason: false,
  leveling: false, levelChannel: null, levelMessage: "{user} reached level **{level}**",
  levelRewards: {}, xp: {}, cases: [], caseSeq: 0,
  pingOnJoin: { enabled: false, channelIds: [], card: true, ghost: false, message: "welcome {user} to {server}! you're member #{count}." },
  sticky: {},
  antiminor: { enabled: false, channels: [], mediaChannels: [], logChannel: null, modRole: null },
  booster: {
    enabled: false, roleId: null, dm: false, logChannel: null, exemptRoles: [],
    perksGuildId: null, perksRoleId: null,
    boostMsg: "thanks for boosting **{server}**, {user}!", unboostMsg: "{user} stopped boosting **{server}**",
  },
});
function G(id) {
  const cur = (db.guilds[id] ||= {});
  for (const [k, v] of Object.entries(DEFAULTS())) {
    if (!(k in cur)) cur[k] = v;
    else if (v && typeof v === "object" && !Array.isArray(v) && cur[k] && typeof cur[k] === "object")
      for (const [k2, v2] of Object.entries(v)) if (!(k2 in cur[k])) cur[k][k2] = v2;
  }
  return cur;
}

