const F = (w, size) => `${size}px ${GlobalFonts.has("Poppins" + w) ? "Poppins" + w : "Arial, Helvetica, sans-serif"}`;

const C = {
  pink: "#ff2e88", white: "#fafafa", desc: "#8b8b92", head: "#6c6c75", gray: "#6c6c75",
  foot: "#6c6c75", line: "rgba(255,255,255,0.06)", top: "#212126", bottom: "#161619",
};
// card body: darker gradient + 2px soft border (same look for every card)
function paintCard(ctx, x, y, w, h, r = 100) {
  ctx.save();
  ctx.shadowColor = "rgba(0,0,0,0.45)"; ctx.shadowBlur = 60; ctx.shadowOffsetY = 20;
  const grad = ctx.createLinearGradient(0, y, 0, y + h);
  grad.addColorStop(0, C.top); grad.addColorStop(1, C.bottom);
  ctx.fillStyle = grad; roundRect(ctx, x, y, w, h, r); ctx.fill();
  ctx.restore();
}
function paintBorder(ctx, x, y, w, h, r = 100) {
  ctx.save(); ctx.strokeStyle = "rgba(255,255,255,0.06)"; ctx.lineWidth = 2;
  roundRect(ctx, x + 1, y + 1, w - 2, h - 2, r - 1); ctx.stroke(); ctx.restore();
}

