      ctx.font = F("b", top3 ? 46 : 40); ctx.fillStyle = top3 ? C.pink : GREY;
      ctx.fillText(String(d.rank), 224, by + (top3 ? -0.5 : 0.5));
      ctx.textAlign = "left";
      ctx.save(); ctx.beginPath(); ctx.arc(318, by, 46, 0, Math.PI * 2); ctx.closePath(); ctx.clip();
      ctx.fillStyle = "#2b2b2f"; ctx.fillRect(272, by - 46, 92, 92);
      if (imgs[d.avatar]) ctx.drawImage(imgs[d.avatar], 272, by - 46, 92, 92);
