const embed = (desc) => ({ color: PINK, description: desc });
const usage = (m, p, u) => m.reply({
  content: `\`${p}${u}\`\n${CMD_DESC[u.split(" ")[0]] || ""}`.trim(),
  allowedMentions: { parse: [], repliedUser: false },
}).catch(() => {});

const idOf = (s) => { const x = /^(?:<(?:@!?|@&|#)(\d{15,25})>|(\d{15,25}))$/.exec(String(s || "").trim()); return x ? x[1] || x[2] : ""; };
async function getMember(m, arg) {
  const id = idOf(arg);
  if (id) return m.guild.members.fetch(id).catch(() => null);
  const q = String(arg || "").replace(/^@/, "").trim();
  if (!q) return null;
  const f = await m.guild.members.search({ query: q, limit: 1 }).catch(() => null);
  return f?.first() ?? null;
}
async function getUser(m, arg) {
  const id = idOf(arg);
  if (id) return client.users.fetch(id).catch(() => null);
  return (await getMember(m, arg))?.user ?? null;
}
function checkChannel(m, ch, need = ["ViewChannel", "SendMessages"]) {
  if (!ch) return "couldn't find that channel";
  if (typeof ch.isTextBased === "function" && !ch.isTextBased()) return "that's not a text channel";
  const me = m.guild.members.me, perms = me && ch.permissionsFor?.(me);
  if (perms && !perms.has(need)) return `i can't post in ${ch} — give me **${need.filter((x) => !perms.has(x)).map((x) => x.replace(/([a-z])([A-Z])/g, "$1 $2")).join(", ")}** there`;
  return null;
}
const typing = (m) => Promise.resolve(m.channel.sendTyping?.()).catch(() => {});
const getChannel = (m, arg) => {
  const id = idOf(arg);
  if (id) return m.guild.channels.cache.get(id) ?? null;
  const t = String(arg || "");
  if (t.startsWith("#") && t.length > 1) return m.guild.channels.cache.find((c) => c.name?.toLowerCase() === t.slice(1).toLowerCase()) ?? null;
  return null;
};
function getRole(m, arg) {
  const id = idOf(arg);
  if (id) return m.guild.roles.cache.get(id) ?? null;
  const q = String(arg || "").replace(/^@/, "").trim().toLowerCase();
  return q ? m.guild.roles.cache.find((r) => r.name.toLowerCase() === q) ?? null : null;
}

function dur(s, defUnit = "s") {
  const m = /^(\d+)(s|m|h|d)?$/i.exec(s || "");
  if (!m) return null;
  const u = { s: 1, m: 60, h: 3600, d: 86400 }[(m[2] || defUnit).toLowerCase()];
  return parseInt(m[1], 10) * u * 1000;
}
const fmtDur = (ms) => {
  const s = Math.round(ms / 1000);
  if (s % 86400 === 0) return `${s / 86400}d`;
  if (s % 3600 === 0) return `${s / 3600}h`;
  if (s % 60 === 0) return `${s / 60}m`;
  return `${s}s`;
};

function canAct(m, target) {
  if (target.id === m.author.id) return "you can't do that to yourself";
  if (target.id === m.guild.ownerId) return "you can't moderate the server owner.";
  if (m.author.id !== m.guild.ownerId && G(m.guild.id).immuneRoles.some((r) => target.roles.cache.has(r)))
    return "that member has an immune role";
  if (m.author.id !== m.guild.ownerId && target.roles.highest.position >= m.member.roles.highest.position)
    return "that member's role is equal to or higher than yours";
  return null;
}

async function record(m, type, user, reason, dur) {
  const g = G(m.guild.id);
  const id = ++g.caseSeq;
  g.cases.push({ id, type, userId: user.id, modId: m.author.id, reason, at: Date.now(), ...(dur ? { dur } : {}) });
  save();
  if (g.modlog) {
    const ch = m.guild.channels.cache.get(g.modlog);
    ch?.send({ embeds: [{ color: PINK, title: `case #${id} • ${type}`, fields: [
      { name: "user", value: `${user} (${user.id})`, inline: true },
      { name: "moderator", value: `${m.author}`, inline: true },
      { name: "reason", value: (dur ? `${dur} — ` : "") + reason.slice(0, 1000) },
    ], timestamp: new Date().toISOString() }] }).catch(() => {});
  }
  return id;
}
async function dmUser(m, user, verb, reason) {
  if (!G(m.guild.id).dmOnAction || typeof user.send !== "function") return;
  // wait (max 1.5s) so the DM lands before a ban/kick removes the mutual server
  await Promise.race([
    user.send({ embeds: [embed(`you were **${verb}** in **${m.guild.name}**\nreason: ${reason}`)] }).catch(() => {}),
    new Promise((r) => setTimeout(r, 1500)),
  ]);
}
function reasonOf(m, args, from) {
  const r = args.slice(from).join(" ").trim();
  if (!r && G(m.guild.id).requireReason) return null;
  return r || "no reason provided";
}

// snipes (memory only)
const stickyTimers = new Map();
const snipes = { del: new Map(), edit: new Map(), react: new Map() };
const pushSnipe = (map, ch, v) => {
  const a = map.get(ch) || [];
  a.unshift(v);
  map.set(ch, a.slice(0, 10));
};

// leveling math
const need = (l) => 5 * l * l + 50 * l + 100;
const cumulative = (l) => { let t = 0; for (let i = 0; i < l; i++) t += need(i); return t; };
const levelOf = (total) => { let l = 0, t = total; while (t >= need(l)) { t -= need(l); l++; } return { level: l, into: t }; };
const xpOf = (g, uid) => (g.xp[uid] ||= { total: 0, last: 0 });

// give reward roles up to `level`; with remove=true also take away the ones above it
async function applyRewards(member, g, level, remove = false) {
  if (!member) return;
  for (const [lvl, roleId] of Object.entries(g.levelRewards)) {
    const has = member.roles.cache.has(roleId);
    if (level >= Number(lvl) && !has) await member.roles.add(roleId).catch(() => {});
    else if (remove && level < Number(lvl) && has) await member.roles.remove(roleId).catch(() => {});
  }
}
// leaderboard / rank order: only members still in the server with xp
async function rankingOf(guild) {
  const cache = guild.members.cache;
  if (cache && guild.memberCount && cache.size < guild.memberCount * 0.9) await guild.members.fetch().catch(() => {});
  const all = Object.entries(G(guild.id).xp).filter(([, u]) => u.total > 0).sort((x, y) => y[1].total - x[1].total);
  return cache && cache.size ? all.filter(([id]) => cache.has(id)) : all;
}

// anti-minor
const SMALLCAPS = { "ᴀ": "a", "ʙ": "b", "ᴄ": "c", "ᴅ": "d", "ᴇ": "e", "ꜰ": "f", "ɢ": "g", "ʜ": "h", "ɪ": "i", "ᴊ": "j", "ᴋ": "k", "ʟ": "l", "ᴍ": "m", "ɴ": "n", "ᴏ": "o", "ᴘ": "p", "ʀ": "r", "ꜱ": "s", "ᴛ": "t", "ᴜ": "u", "ᴠ": "v", "ᴡ": "w", "ʏ": "y", "ᴢ": "z" };
// minors write their age backwards to evade: 31 41 51 61 71 = 13 14 15 16 17
const RVS = { 31: 13, 41: 14, 51: 15, 61: 16, 71: 17 };

function minorNorm(text) {
  return String(text).normalize("NFKC").replace(/(\d)[\uFE0E\uFE0F]?\u20E3/g, "$1").replace(/[\uFE0E\uFE0F]/g, "")
    .replace(/[\u200B-\u200D\u2060\uFEFF\u00AD]/g, "")
    .replace(/[\u2010-\u2015\u2212\uFE63\uFF0D]/g, "-")
    .replace(/[ᴀ-ᴢʙʜɪʟɴʀʏꜰꜱ]/g, (c) => SMALLCAPS[c] || c)
    .replace(/\u{1F1F2}/gu, "m").replace(/\u{1F1E7}/gu, "b").replace(/\u{1F1EE}/gu, "i")
    .replace(/<a?:\w+:\d+>|<[@#][!&]?\d+>/g, " ").replace(/https?:\/\/\S+/g, " ").replace(/\s+/g, " ").toLowerCase();
}

// two-digit ages written like an intro: "51m" "im 62" "48 yo" "52 bottom" ... returns [n, n, ...]
// careful with measurements: "60m away" "50m deep" "70f outside" "60 kg" "51 cm" "51m2" "ran 60m" are NOT ages
function introAgeScan(t) {
  const NOT_SELF = /\b(?:my|his|her|their|our|your|ur|he|she|they|he's|she's|hes|shes|friend|sister|brother|bro|sis|son|daughter|kid|cousin|girlfriend|boyfriend|gf|bf|is|was|are|were|its|it's|level|lvl|rank|size|room|page|chapter|season|episode|part|number|no|version|than|over|under|for|at|about|around|since|until|till|after|before|next|every|each|per)\b[^.!?\n]{0,25}$/;
  const PRE_MEAS = /\b(?:swim|swam|swimming|run|ran|running|jog|jogged|walk|walked|walking|drive|driving|distance|dist|height|length|width|depth|within|range|radius|diameter|lap|laps|sprint|dash|pool|track|temp|temperature|degrees?|outside|weather|weigh|weighs|weight|price|cost|budget|approx|approximately)\b[^.!?\n]{0,25}$/;
  const AFTER_MEAS = /^(?:[²³\d]|\/s)|^\s*(?:away|long|tall|high|deep|wide|apart|from|per|radius|diameter|below|above|underwater|x\b)/;
  const TEMP = /\b(?:temp|temperature|degrees?|outside|weather|celsius|fahrenheit)\b|°/;
  const BAD_UNIT = /^\s*(?:cm|kg|lbs?|pounds?|inch(?:es)?|ft|feet|mins?|minutes?|hours?|hrs?|days?|weeks?|months?|years?(?!\s*old)|yrs?(?!\s*old)|gb|tb|mb|kb|fps|hz|mph|kmh|km|mm|meters?|metres?|%|am\b|pm\b|st\b|nd\b|rd\b|th\b|k\b|x\b|\$|€|:\d)/;
  const UNIT = "(?!\\s*(?:cm|kg|lbs?|inch|inches|in\\b|ft|feet|mins?|hours?|hrs?|days?|weeks?|months?|gb|tb|mb|fps|hz|mph|km|mm|%|\\$|€|\"|'|:\\d|st\\b|nd\\b|rd\\b|th\\b|k\\b|x\\b))";
  const okp = (i) => !/[.:,\/$€£#\d]/.test(t[i - 1] || "");
  const bad = (i) => NOT_SELF.test(t.slice(0, i)) || PRE_MEAS.test(t.slice(Math.max(0, i - 30), i));
  const out = [];
  let r;
  const S = /\b(?:i'?m|im|i am|iam|aged?|age is|age:|just turned|turning)\s*:?\s*(\d{2})\b/g;
  while ((r = S.exec(t))) if (!BAD_UNIT.test(t.slice(S.lastIndex)) && !PRE_MEAS.test(t.slice(Math.max(0, r.index - 30), r.index))) out.push(+r[1]);
  const Y = /\b(\d{2})\s*(?:yo|y\/o|y\.o\.?|yrs? old|years? old)\b/g;
  while ((r = Y.exec(t))) if (okp(r.index) && !bad(r.index)) out.push(+r[1]);
  const G = /\b(\d{2})\s*[\/|,.\-]?\s*(?:m|f|male|female|boy|girl|guy|nb|trans)\b(?![a-z'])/g;
  while ((r = G.exec(t))) {
    const isF = /(?:^|[^a-z])f$/.test(r[0]);
    if (okp(r.index) && !bad(r.index) && !AFTER_MEAS.test(t.slice(G.lastIndex)) && !(isF && TEMP.test(t))) out.push(+r[1]);
  }
  const LD = new RegExp("^\\W{0,8}(?:(?:dms?|dm's)\\s+open\\s+)?(\\d{2})(?!\\d)" + UNIT + "\\s*(?:[mf]\\b|male|female|boy|guy|bttm|btm|bottom|top|vers|verse|femboy|twink|dms?\\b|hmu|lf\\b|looking|lookin|horny|here|[|,.!~\\-:]|$)").exec(t);
  if (LD && !AFTER_MEAS.test(t.slice(LD.index + LD[0].length)) && !(/(?:^|[^a-z])f$/.test(LD[0]) && TEMP.test(t))) out.push(+LD[1]);
  return out.filter((n) => n >= 31 && n <= 99);
}

function minorCheck(text, dbg) {
  const t = minorNorm(text);
  // "underage" counts only when it's about the speaker: not "no underage pls" / "don't be underage" / "ur underage" (said to someone else)
  const uaHit = [...t.matchAll(/\bunder\s?age\b/g)].some((x) => !/(?:\b(?:no|not|nor|dont|don't|do not|never|without|ban|must not be|please no|pls no)\b|\b(?:you|u|ur|youre|you're|your)\b)[^.!?\n]{0,20}$/.test(t.slice(0, x.index)));
  if (uaHit || /\b(?:i'?m|im|i am|iam)\s+(?:a\s+)?minor\b(?!\s+(?:in|at|key|league|issue|detail|problem|change|bug)\b)|^\W{0,4}minor\W{0,4}$|\bstill (?:in )?(?:high ?school|hs|middle school|school)\b/.test(t)) { if (dbg) dbg.kind = "keyword"; return "minor keyword"; }
  // evasion markers: each one flags the message on its own (Ⓜ️ / a lone 🇲 / 🔁 🔂 🔃 🔄 / the word "reversed" / small-caps ᴄʜᴀɴɴᴇʟ)
  const rawT = String(text);
  if (/[\u24C2\u{1F501}-\u{1F504}]|\u{1F1F2}|ᴄʜᴀɴɴᴇʟ/u.test(rawT) || /\breversed\b/.test(t)) { if (dbg) dbg.kind = "coded"; return "evasion marker"; }
  const nowY = new Date().getFullYear();
  // words right before a number that mean the age is NOT about the speaker
  const NOT_SELF = /\b(?:my|his|her|their|our|your|ur|he|she|they|he's|she's|hes|shes|friend|sister|brother|bro|sis|son|daughter|kid|cousin|girlfriend|boyfriend|gf|bf|is|was|are|were|its|it's|level|lvl|rank|size|room|page|chapter|season|episode|part|number|no|version|than|over|under|for|at|about|around|since|until|till|after|before|next|every|each|per)\b[^.!?\n]{0,25}$/;
  const BAD_UNIT = /^\s*(?:cm|kg|lbs?|pounds?|inch(?:es)?|ft|feet|mins?|minutes?|hours?|hrs?|days?|weeks?|months?|years?(?!\s*old)|yrs?(?!\s*old)|gb|tb|mb|kb|fps|hz|mph|kmh|km|mm|meters?|metres?|%|am\b|pm\b|st\b|nd\b|rd\b|th\b|k\b|x\b|\$|€|:\d)/;
  const ages = [];
  const add = (n, kind) => { n = +n; if ((n >= 10 || kind === "young") && n <= 99) ages.push({ n, kind }); };
  const ok = (idx) => !/[.:,\/$€£#\d]/.test(t[idx - 1] || "");
  const notSelf = (idx) => NOT_SELF.test(t.slice(0, idx));
  let r;
  const A = /\b(?:i'?m|im|i am|iam|aged?|age is|age:|just turned|turning)\s*:?\s*(\d{1,2})\b/g;
  while ((r = A.exec(t))) if (!BAD_UNIT.test(t.slice(A.lastIndex))) add(r[1], "self");
  const B = /\b(\d{1,2})\s*(?:yo|y\/o|y\.o\.?|yrs? old|years? old)\b/g;
  while ((r = B.exec(t))) if (ok(r.index) && !notSelf(r.index)) add(r[1], "intro");
  const C = /\b(\d{1,2})\s*[\/|,.\-]?\s*(?:m|f|male|female|boy|girl|guy|nb|trans)\b(?![a-z'])/g;
  while ((r = C.exec(t))) if (ok(r.index) && !notSelf(r.index) && !/^\s*(?:away|long|tall|high|deep|wide|apart|from|per|\/s)/.test(t.slice(C.lastIndex))) add(r[1], "intro");
  const E = /\b(?:born|bday|b-day|birth ?year)\b\D{0,12}\b((?:19|20)\d\d)\b/g;
  while ((r = E.exec(t))) add(nowY - +r[1], "self");
  // (learned from ,study on ~300 mod decisions) -- profile-style intros that never say "im"/"yo":
  const UNIT = "(?!\\s*(?:cm|kg|lbs?|inch|inches|in\\b|ft|feet|mins?|hours?|hrs?|days?|weeks?|months?|gb|tb|mb|fps|hz|mph|km|mm|%|\\$|€|\"|'|:\\d|st\\b|nd\\b|rd\\b|th\\b|k\\b|x\\b))";
  // "16 mp open" / "13 bottom looking for top" / "17" / "14 dms open": the age is the first thing in the message
  const L = new RegExp("^\\W{0,8}(?:(?:dms?|dm's)\\s+open\\s+)?(?:m\\s?)?(1[0-7])(?!\\d)" + UNIT + "\\s*(?:[mf]\\b|male|female|boy|guy|bttm|btm|bottom|top|vers|verse|femboy|twink|dms?\\b|mp\\b|pm\\b|hmu|lf\\b|looking|lookin|horny|here|black|big|chubby|[|,.!~\\-:]|$)").exec(t);
  if (L) add(L[1], "lead");
  // "18-4 m" = 18 minus 4 = 14 (subtraction trick): only when it ends like an intro (m/f/male...) and the result is 10-17
  const MATH = /(?<![\d.:\/$€£#-])(1[89]|[2-4]\d)\s*[-−–]\s*([1-9])(?!\d)\s*(?:[mf]\b|male|female|boy|guy)/g;
  while ((r = MATH.exec(t))) add(+r[1] - +r[2], "math");
  // single digit ages are minors too ("9 year old man ..."): only the explicit "year old" forms (a bare "9m" is just an OCR-clipped "19m")
  const YG = /(?<![\d.])([5-9])\s*(?:yo|y\/o|y\.o\.?|yrs? old|years? old)\b/g;
  while ((r = YG.exec(t))) if (!notSelf(r.index)) add(r[1], "young");
  // "m17" / "M 16" (gender letter BEFORE the age; only m: "f13" is a game)
  const M2 = new RegExp("(?<![a-z0-9])m\\s?(1[0-7])(?!\\d)" + UNIT, "g");
  while ((r = M2.exec(t))) if (!notSelf(r.index)) add(r[1], "intro");
  // "71🔄" / "61 reversed" / "41 flipped": age written backwards, only when a reverse/flip marker sits next to it
  const RV = /(?<!\d)([1-9]\d)(?!\d)/g;
  while ((r = RV.exec(t))) {
    const back = +r[1].split("").reverse().join("");
    if (back >= 10 && back <= 17 && /revers(?:e|ed|ing)|flip(?:ped)?|backwards?|inverted|rewind|mirror(?:ed)?|upside|🔁|🔂|🔄|🔃|⏪|↔|↩|🙃/.test(t.slice(Math.max(0, r.index - 18), r.index + 20))) add(back, "reversed");
  }
  // ---- coded / obfuscated age formats (curated from mod logs: 1 3M, b-13, !7, 10+3, 3teen, si❌teen, 🇲1️⃣3️⃣, -18 ...) ----
  const NOCPU = !/\b(?:intel|cpu|ryzen|core|gen|processor|laptop|ram|gpu|pc|iphone|ipad|nvidia|amd)\b/.test(t);   // "i5/i7" chips
  const ONE = "[i!|l1]";                                            // the "1" of 13-17 written as 1 / i / ! / | / l
  const OBF1 = "(?:[i!|l]\\s?-?\\s?|1(?:\\s-?\\s?|-\\s?))";           // obfuscated "1": i3  !7  1 3  1-3  (a plain "13" is handled elsewhere)
  const GATE = "(?=\\s*(?:[mf]\\b|male|female|boy|girl|guy|bttm|btm|bottom|top|vers|verse|femboy|twink|dms?\\b|md\\b|bi\\b|lf\\b|looking|lookin|open|hmu|horny|here|and\\b|&|\\+|[|,.!~\\-:)\\]\\/]|$))";
  const NEG = /(?:\b(?:no|not|nor|dont|don't|do not|never|without|ban|if|anyone|anybody|everyone|people|ppl|users?|kids?|those|who|you|u|ur|youre|you're|your)\b)[^.!?\n]{0,25}$/;
  const AWAY = /^\s*(?:away|long|tall|high|deep|wide|apart|from|per)/;
  // raw emoji "🇲7️⃣" / "Ⓜ️5": the leading 1 is dropped
  const rawM = /[\u{1F1F2}\u24C2]\uFE0F?\s?([3-7])(?:\uFE0F?\u20E3)?(?!\d)/u.exec(String(text));
  if (rawM) add(10 + +rawM[1], "coded");
  // lead position, 1 written oddly: "1 4 m" / "i5 bottom" / "!7" / "mi 3" / "m i 3"
  const LC = new RegExp("^\\W{0,8}(?:m\\s?)?" + ONE + "\\s?([3-7])(?!\\d)" + UNIT + GATE).exec(t);
  if (LC && NOCPU) add(10 + +LC[1], "coded");
  // obfuscated 1 + gender/role letter: "1 3M" "1-4b" "I 3M" "i5m"
  const OB = new RegExp("(?<![\\d.:\\/$€£#a-z])" + OBF1 + "([3-7])\\s?-?\\s?(?:m|b|f|dm|md|top|bottom|btm|bttm)(?![a-z0-9'])" + UNIT, "g");
  while ((r = OB.exec(t))) if (NOCPU && !notSelf(r.index) && !AWAY.test(t.slice(OB.lastIndex))) add(10 + +r[1], "coded");
  // role/gender letter BEFORE the age: "b-13" "bottom14" "dm15" "top17" "md16" "b1-5" "m-16" "m1-4" "M1 3" "MI 3"
  const PF = new RegExp("(?<![a-z0-9])(?:(?:b|bottom|btm|bttm|top|dm|md)-?|m\\s?-?\\s?)(?:(1[3-7])|" + OBF1 + "([3-7]))(?!\\d)" + UNIT, "g");
  while ((r = PF.exec(t))) if (NOCPU && !notSelf(r.index)) add(r[1] ? +r[1] : 10 + +r[2], "coded");
  // role letter AFTER the age: "13b" "14bottom" "15dm" "16md" "17top" "13-b"  (spaced "15 top" only when it ends like an intro)
  const RL = "(?:b|bottom|btm|bttm|top|dm|dms|md|vers)";
  const SF = new RegExp("(?<![\\d.:\\/$€£#a-z])(1[3-7])(?:-?" + RL + "(?![a-z0-9'])|\\s" + RL + "(?![a-z0-9'])" + GATE + ")" + UNIT, "g");
  while ((r = SF.exec(t))) if (!notSelf(r.index)) add(r[1], "coded");
  // age range "13-16" (only when it ends like an intro)
  const RG = new RegExp("(?<![\\d.:\\/$€£#-])(1[3-7])\\s?-\\s?(1[3-8])(?!\\d)" + UNIT + GATE, "g");
  while ((r = RG.exec(t))) if (+r[2] > +r[1] && !notSelf(r.index)) add(r[1], "coded");
  // "10+3" .. "10+7" = 13..17 (not "10+3=13")
  const PL = new RegExp("(?<![\\d.:\\/$€£#+-])10\\s?\\+\\s?([3-7])(?![\\d.]|\\s*[=x*/])" + UNIT + GATE, "g");
  while ((r = PL.exec(t))) if (!notSelf(r.index)) add(10 + +r[1], "coded");
  // "under 18" shorthands: "-18" "-m18" "-18m" / "18-" "18-lower" / "below 18" (not said about others: "no below 18")
  const UN1 = new RegExp("(?<![\\w.:\\/$€£#-])-\\s?m?\\s?18(?![\\d+°])" + UNIT + GATE, "g");
  while ((r = UN1.exec(t))) if (!notSelf(r.index)) add(17, "coded");
  const UN2 = /(?<![\w.:\/$€£#-])18\s?-(?=\s*(?:lower|below|under|minus|[mf]\b|male|female|boy|guy|dms?\b|looking|here|$|[|,.!~:]))/g;
  while ((r = UN2.exec(t))) if (!notSelf(r.index)) add(17, "coded");
  const UN3 = new RegExp("\\bbelow\\s?18(?![\\d+])" + UNIT, "g");
  while ((r = UN3.exec(t))) if (!NEG.test(t.slice(0, r.index))) add(17, "coded");
  // "1M3" .. "1M7" (M written between the digits)
  const IM = new RegExp("(?<![\\d.:\\/$€£#a-z])1\\s?m\\s?([3-7])(?!\\d)" + UNIT + GATE, "g");
  while ((r = IM.exec(t))) if (!notSelf(r.index)) add(10 + +r[1], "coded");
  // "3teen" "4teen" .. "7teen" and "si❌teen"/"si✖teen"/"si×teen" (never real words)
  const TN = /(?<![a-z0-9])([3-7])teen(?![a-z])|(?<![a-z])si[❌✖✕×]teen(?![a-z])/g;
  while ((r = TN.exec(t))) add(r[1] ? 10 + +r[1] : 16, "coded");
  // spelled-out ages (also l33t): only when it's about the speaker ("im sixteen" / "sixteen yo" / "sixteen m" / just "sixteen")
  const WD = /(?<![a-z])(th[i1]rt[e3]{2}n|fou?rt[e3]{2}n|f[i1]ft[e3]{2}n|s[i1]xt[e3]{2}n|sev[e3]nt[e3]{2}n)(?![a-z0-9])/g;
  const WDN = { th: 13, fo: 14, fi: 15, si: 16, s1: 16, se: 17 };
  while ((r = WD.exec(t))) {
    const rest = t.slice(WD.lastIndex), pre = t.slice(0, r.index);
    const self = /\b(?:i'?m|im|i am|iam|am|aged?|age is|turned|turning|just turned)\s*(?:a\s)?$/.test(pre.slice(-16));
    const yo = /^\s*(?:yo\b|y\/o|y\.o|yrs? old|years? old|year-old)/.test(rest);
    const lead = /^\W*$/.test(pre) && /^\s*(?:$|[|,.!~\-:]|(?:m|f|male|female|boy|guy)\b)/.test(rest);
    if (self || yo || lead) add(WDN[r[1].slice(0, 2)], "coded");
  }
  // reversed-age evasion: 31 41 51 61 71 written like an intro ("51m", "im 71", "41 yo", "m61", "71 bottom") = 13..17
  for (const n of introAgeScan(t)) if (RVS[n]) add(RVS[n], "reversed");
  const MR = new RegExp("(?<![a-z0-9])m\\s?(31|41|51|61|71)(?!\\d)" + UNIT, "g");
  while ((r = MR.exec(t))) if (!notSelf(r.index)) add(RVS[r[1]], "reversed");
  const minors = ages.filter((x) => x.n <= 17);
  if (!minors.length) return null;
  const adultSelf = ages.some((x) => x.n >= 18 && x.kind === "self") || /\b(?:1[89]|[2-9]\d)\s*\+/.test(t);
  // "im 15 jk im 25" -> clean, but "15 m (looks 25)" -> still flagged
  if (adultSelf && minors.every((x) => x.kind === "self")) return null;
  if (dbg) dbg.kind = minors[0].kind;
  return `age ${minors[0].n}`;
}

// ---------------------------------------------------------------------
//  Commands
// ---------------------------------------------------------------------
const cmds = new Map();
const def = (names, perm, fn) => { for (const n of [].concat(names)) cmds.set(n, { perm, fn, name: [].concat(names)[0] }); };

function commandCard(m, p, cat, row) {
  const [name, args, desc] = row;
  const c = cmds.get(name);
  const aliases = [...cmds.entries()].filter(([n, x]) => x.name === name && n !== name).map(([n]) => p + n);
  const key = c?.perm ? Object.keys(P).find((k) => P[k] === c.perm) : null;
  return card(m, { eyebrow: `${cat} • command`, title: p + name, subtitle: desc, footL: "<> required · [] optional", blocks: [
    { usage: { cmd: p + name, args: args || "" } },
    { label: "Aliases", value: aliases.join(" ") || "none" },
    { label: "Permissions", value: key ? key.replace(/([a-z])([A-Z])/g, "$1 $2") : "none" },
  ] });
}

// ---- help
def("help", null, async (m, a, p) => {
  const q = (a[0] || "").toLowerCase().replace(p, "");
  const n = parseInt(q, 10);
  if (q && !PAGES[n]) {
    const cat = CATS.find((c) => c.toLowerCase() === q);
    if (cat) return m.reply({ ...helpMessage(firstPageOf(cat), m.author.id, p), allowedMentions: { repliedUser: false } });
    const canon = cmds.get(q)?.name || q;
    for (const pg of Object.values(PAGES)) {
      const row = pg.rows.find((r) => r[0] === canon);
      if (row) return commandCard(m, p, pg.cat, row);
    }
  }
  const page = PAGES[n] ? n : 5;
  await m.reply({ ...helpMessage(page, m.author.id, p), allowedMentions: { repliedUser: false } });
});

// ---- moderation
def("ban", P.BanMembers, async (m, a, p) => {
  if (!a[0]) return usage(m, p, "ban <@user|id> [reason]");
  const user = await getUser(m, a[0]);
  if (!user) return err(m, "couldn't find that user");
  const reason = reasonOf(m, a, 1);
  if (!reason) return err(m, "a reason is required");
  const mem = await m.guild.members.fetch(user.id).catch(() => null);
  if (mem) { const e = canAct(m, mem); if (e) return err(m, e); if (!mem.bannable) return err(m, "i can't ban that member"); }
  await dmUser(m, user, "banned", reason);
  const done = await m.guild.members.ban(user.id, { reason: `${m.author.username}: ${reason}` }).catch(() => null);
  if (!done) return err(m, "failed to ban — check my role hierarchy");
  const id = await record(m, "ban", user, reason);
  (await caseReply(m, id, "ban", user, reason, { mem })) || ok(m, `banned **${user.username}** | ${reason} (case #${id})`);
});

def("unban", P.BanMembers, async (m, a, p) => {
  const id = idOf(a[0]);
  if (!id) return usage(m, p, "unban <id> [reason]");
  const reason = reasonOf(m, a, 1);
  if (!reason) return err(m, "a reason is required");
  const done = await m.guild.bans.remove(id, reason).catch(() => null);
  if (!done) return err(m, "that user isn't banned");
  const user = await client.users.fetch(id).catch(() => ({ id, username: id, toString: () => id }));
  const uid = await record(m, "unban", user, reason);
  (await caseReply(m, uid, "unban", user, reason)) || ok(m, `unbanned **${user.username}**`);
});

def("kick", P.KickMembers, async (m, a, p) => {
  const mem = await getMember(m, a[0]);
  if (!mem) return usage(m, p, "kick <@user> [reason]");
  const e = canAct(m, mem); if (e) return err(m, e);
  const reason = reasonOf(m, a, 1);
  if (!reason) return err(m, "a reason is required");
  await dmUser(m, mem.user, "kicked", reason);
  const done = await mem.kick(`${m.author.username}: ${reason}`).catch(() => null);
  if (!done) return err(m, "failed to kick — check my role hierarchy");
  const id = await record(m, "kick", mem.user, reason);
  (await caseReply(m, id, "kick", mem.user, reason, { mem })) || ok(m, `kicked **${mem.user.username}** | ${reason} (case #${id})`);
});

def("timeout", P.ModerateMembers, async (m, a, p) => {
  const mem = await getMember(m, a[0]);
  const ms = dur(a[1], "m");
  if (!mem || !ms) return usage(m, p, "timeout <@user> <duration> [reason]");
  if (ms > 28 * 86400000) return err(m, "max timeout is 28d");
  const e = canAct(m, mem); if (e) return err(m, e);
  const reason = reasonOf(m, a, 2);
  if (!reason) return err(m, "a reason is required");
  await dmUser(m, mem.user, `timed out for ${fmtDur(ms)}`, reason);
  const done = await mem.timeout(ms, `${m.author.username}: ${reason}`).catch(() => null);
  if (!done) return err(m, "failed to timeout — check my role hierarchy");
  const id = await record(m, "timeout", mem.user, reason, fmtDur(ms));
  (await caseReply(m, id, "timeout", mem.user, reason, { mem, dur: fmtDur(ms) })) || ok(m, `timed out **${mem.user.username}** for **${fmtDur(ms)}** | ${reason} (case #${id})`);
});

def("untimeout", P.ModerateMembers, async (m, a, p) => {
  const mem = await getMember(m, a[0]);
  if (!mem) return usage(m, p, "untimeout <@user> [reason]");
  if (!mem.isCommunicationDisabled()) return err(m, `**${mem.user.username}** isn't timed out`);
  const reason = reasonOf(m, a, 1);
  if (!reason) return err(m, "a reason is required");
  const done = await mem.timeout(null, reason).catch(() => null);
  if (!done) return err(m, "failed to remove the timeout — check my role hierarchy");
  const uid = await record(m, "untimeout", mem.user, reason);
  (await caseReply(m, uid, "untimeout", mem.user, reason, { mem })) || ok(m, `removed timeout from **${mem.user.username}**`);
});

def("warn", P.ModerateMembers, async (m, a, p) => {
  if (!a[0]) return usage(m, p, "warn <@user> [reason]");
  const mem = await getMember(m, a[0]);
  if (!mem) return say(m, "something went wrong running that command.");
  const e = canAct(m, mem); if (e) return err(m, e);
  const reason = reasonOf(m, a, 1);
  if (!reason) return err(m, "a reason is required");
  const id = await record(m, "warn", mem.user, reason);
  const n = G(m.guild.id).cases.filter((c) => c.type === "warn" && c.userId === mem.id).length;
  await dmUser(m, mem.user, "warned", reason);
  (await caseReply(m, id, "warn", mem.user, reason, { mem })) || ok(m, `warned **${mem.user.username}** (${n} total) | ${reason} (case #${id})`);
});

def("warnings", null, async (m, a, p) => {
  const user = a[0] ? await getUser(m, a[0]) : null;
  const list = G(m.guild.id).cases.filter((c) => c.type === "warn" && (!user || c.userId === user.id)).sort((x, y) => y.id - x.id);
  if (!list.length) return say(m, user ? `**${user.username}** has no warnings` : "no warnings in this server");
  return say(m, await caseText(m, list, user ? `⚠️ warnings for **${user.username}**: ${list.length} total\n` : `⚠️ all warnings: ${list.length} total\n`, false));
});

def("cases", P.ModerateMembers, async (m, a, p) => {
  const user = a[0] ? await getUser(m, a[0]) : null;
  const list = G(m.guild.id).cases.filter((c) => !user || c.userId === user.id).sort((x, y) => y.id - x.id);
  if (!list.length) return say(m, "no cases found");
  return say(m, await caseText(m, list, user ? `🗂️ cases for **${user.username}**: ${list.length} total\n` : `🗂️ all cases: ${list.length} total\n`, true));
});

// plain-text case list shared by history / cases / warnings (newest first, trimmed to Discord's 2000 chars)
async function caseText(m, list, head, withType) {
  const names = {};
  for (const id of new Set(list.map((c) => c.modId))) names[id] = await userName(m, id);
  const esc = (t) => String(t).replace(/\n+/g, " ").slice(0, 150);
  let out = head, shown = 0;
  for (const c of list) {
    const { dur, reason } = splitCase(c);
    const hasReason = reason && reason !== "no reason provided";
    const lead = withType ? ` **${c.type}**${dur ? ` \`${dur}\`` : ""} ·` : "";
    const line = `\n\`#${c.id}\`${lead} <@${c.userId}>${hasReason ? `: ${esc(reason)}` : ""} · by ${names[c.modId]} · <t:${Math.floor(c.at / 1000)}:R>`;
    if (out.length + line.length > 1900) break;
    out += line; shown++;
  }
  if (shown < list.length) out += `\n… and ${list.length - shown} more`;
  return out;
}
// ,history <@user|id> -> every case of a member
def(["history", "hist"], P.ModerateMembers, async (m, a, p) => {
  if (!a[0]) return usage(m, p, "history <@user|id>");
  const user = await getUser(m, a[0]);
  if (!user) return err(m, "couldn't find that user");
  const list = G(m.guild.id).cases.filter((c) => c.userId === user.id).sort((x, y) => y.id - x.id);
  if (!list.length) return say(m, `no cases for **${user.username}**`);
  return say(m, await caseText(m, list, `🗂️ cases for **${user.username}**: ${list.length} total\n`, true));
});

async function msPayload(guild, client, page, ownerId, prefix) {
  const PER = 15;
  const by = {};
  const cases = G(guild.id).cases;
  for (const c of cases) { (by[c.modId] ||= { n: 0 }).n++; by[c.modId][c.type] = (by[c.modId][c.type] || 0) + 1; }
  const all = Object.entries(by).sort((x, y) => y[1].n - x[1].n);
  const pages = Math.max(1, Math.ceil(all.length / PER));
  page = Math.min(Math.max(page || 1, 1), pages);
  const blocks = await Promise.all(all.slice((page - 1) * PER, page * PER).map(async ([id, st], i) => {
    const usr = await client.users.fetch(id).catch(() => null);
    const kinds = Object.entries(st).filter(([k]) => k !== "n").sort((x, y) => y[1] - x[1]).map(([k, v]) => `${k} ${v}`).join(" · ");
    return { lb: { rank: (page - 1) * PER + i + 1, name: usr?.username ?? "unknown user", sub: kinds, value: st.n, unit: "actions",
      avatar: usr ? usr.displayAvatarURL({ extension: "png", size: 128 }) : null } };
  }));
  const buf = await renderCard({ eyebrow: "Moderation • mod stats", title: guild.name, counter: [page, pages], blocks,
    footL: `${cases.length} total case${cases.length === 1 ? "" : "s"}`, footR: "ranked by actions" });
  const payload = { files: [new AttachmentBuilder(buf, { name: "modstats.png" })], components: [] };
  if (pages > 1) {
    const mk = (id, tag) => new ButtonBuilder().setCustomId(`ms:go:${ownerId}:${id}:${tag}`).setStyle(ButtonStyle.Secondary);
    payload.components = [new ActionRowBuilder().addComponents(
      mk(page - 1 < 1 ? pages : page - 1, "prev").setEmoji("◀️"),
      mk(page, "cur").setLabel(`${page} / ${pages}`),
      mk(page + 1 > pages ? 1 : page + 1, "next").setEmoji("▶️"))];
  }
  return payload;
}
def(["modstats", "mods"], P.ModerateMembers, async (m, a, p) => {
  if (!G(m.guild.id).cases.length) return info(m, "no moderation actions recorded yet");
  const payload = await msPayload(m.guild, m.client, 1, m.author.id, p);
  return m.reply({ ...payload, allowedMentions: { parse: [], repliedUser: false } }).catch((e) => console.error("[modstats]", e.message));
});

def(["modconfig", "modset", "modsetup"], P.ManageGuild, async (m, a, p) => {
  const g = G(m.guild.id);
  const sub = (a[0] || "status").toLowerCase();
  const onoff = (v) => ({ on: true, off: false, enable: true, disable: false }[(v || "").toLowerCase()]);
  if (sub === "status") {
    return sendCard(m, { eyebrow: "Moderation settings", badge: g.modlog ? "LOGGING" : "NO LOG", tone: g.modlog ? "good" : "neutral", glow: true,
      footL: p + "modconfig", footR: g.modlog ? "logging" : "not logging", fields: [
      ["Mod-log channel", g.modlog ? chLabel(m, g.modlog) : "not set"],
      ["DM on action", g.dmOnAction ? "on" : "off"],
      ["Require reason", g.requireReason ? "on" : "off"],
      ["Immune roles", g.immuneRoles.length ? g.immuneRoles.map((r) => roleLabel(m, r)).join(", ") : "none"],
    ] });
  }
  if (sub === "log") {
    if ((a[1] || "").toLowerCase() === "off") { g.modlog = null; save(); return ok(m, "mod log disabled"); }
    const ch = getChannel(m, a[1]);
    if (!ch) return usage(m, p, "modconfig log <#channel|off>");
    const bad = checkChannel(m, ch, ["ViewChannel", "SendMessages", "EmbedLinks"]);
    if (bad) return err(m, bad);
    g.modlog = ch.id; save(); return ok(m, `mod log → ${ch}`);
  }
  if (sub === "dm" || sub === "reason") {
    const v = onoff(a[1]);
    if (v === undefined) return usage(m, p, `modconfig ${sub} <on|off>`);
    if (sub === "dm") g.dmOnAction = v; else g.requireReason = v;
    save(); return ok(m, `${sub === "dm" ? "dm on action" : "require reason"}: **${v ? "on" : "off"}**`);
  }
  if (sub === "immune") {
    const act = (a[1] || "").toLowerCase();
    const role = getRole(m, a.slice(2).join(" "));
    if (!["add", "remove"].includes(act) || !role) return usage(m, p, "modconfig immune <add|remove> <@role>");
    g.immuneRoles = act === "add" ? [...new Set([...g.immuneRoles, role.id])] : g.immuneRoles.filter((x) => x !== role.id);
    save(); return ok(m, `**${role.name}** ${act === "add" ? "is now" : "is no longer"} immune to moderation`);
  }
  usage(m, p, "modconfig [status|log|dm|reason|immune]");
});

// ---- channel control
const everyone = (m) => m.guild.roles.everyone;
const chanEdit = (ch, role, perms, reason) => ch.permissionOverwrites.edit(role, perms, reason ? { reason } : undefined).then(() => true).catch(() => false);
const textChannels = (m) => m.guild.channels.cache.filter((c) => c.type === ChannelType.GuildText);

def("lock", P.ManageChannels, async (m, a) => {
  const target = getChannel(m, a[0]), ch = target || m.channel;
  const reason = a.slice(target ? 1 : 0).join(" ") || "no reason provided";
  if (!(await chanEdit(ch, everyone(m), { SendMessages: false }, reason))) return err(m, `i can't edit ${ch} — check my permissions`);
  ok(m, `locked ${ch} | ${reason}`);
});
def("unlock", P.ManageChannels, async (m, a) => {
  const ch = getChannel(m, a[0]) || m.channel;
  if (!(await chanEdit(ch, everyone(m), { SendMessages: null }))) return err(m, `i can't edit ${ch} — check my permissions`);
  ok(m, `unlocked ${ch}`);
});
def("hide", P.ManageChannels, async (m, a) => {
  const ch = getChannel(m, a[0]) || m.channel;
  if (!(await chanEdit(ch, everyone(m), { ViewChannel: false }))) return err(m, `i can't edit ${ch} — check my permissions`);
  ok(m, `hidden ${ch}`);
});
def("unhide", P.ManageChannels, async (m, a) => {
  const ch = getChannel(m, a[0]) || m.channel;
  if (!(await chanEdit(ch, everyone(m), { ViewChannel: null }))) return err(m, `i can't edit ${ch} — check my permissions`);
  ok(m, `unhidden ${ch}`);
});
def("lockdown", P.Administrator, async (m, a) => {
  const off = (a[0] || "").toLowerCase() === "off";
  const chans = textChannels(m);
  let n = 0;
  for (const ch of chans.values()) if (await chanEdit(ch, everyone(m), { SendMessages: off ? null : false })) n++;
  ok(m, `${off ? "unlocked" : "locked"} **${n}** / ${chans.size} channels`);
});
def("slowmode", P.ManageChannels, async (m, a, p) => {
  if (!a[0]) return usage(m, p, "slowmode <seconds|duration|off>");
  const ms = a[0].toLowerCase() === "off" ? 0 : dur(a[0], "s");
  if (ms === null || ms > 21600000) return err(m, "invalid value (0 – 6h)");
  const done = await m.channel.setRateLimitPerUser(ms / 1000).catch(() => null);
  if (!done) return err(m, "i can't change the slowmode here — check my permissions");
  ok(m, ms === 0 ? "slowmode disabled" : `slowmode set to **${fmtDur(ms)}**`);
});
def("botclear", P.ManageMessages, async (m) => {
  const msgs = await m.channel.messages.fetch({ limit: 100 });
  const bots = msgs.filter((x) => x.author.bot);
  const del = await m.channel.bulkDelete(bots, true).catch(() => null);
  const r = await ok(m, `deleted **${del?.size ?? 0}** bot messages`, "send");
  setTimeout(() => r?.delete().catch(() => {}), 3000);
});

// ---- leveling
def("leveling", P.ManageGuild, async (m, a) => {
  const g = G(m.guild.id);
  const v = (a[0] || "").toLowerCase();
  if (v !== "on" && v !== "off") return say(m, `leveling is currently **${g.leveling ? "on" : "off"}**. use \`leveling <on|off>\`.`);
  g.leveling = v === "on";
  save();
  ok(m, `leveling **${g.leveling ? "enabled" : "disabled"}**`);
});
def("levelchannel", P.ManageGuild, async (m, a, p) => {
  const g = G(m.guild.id);
  if ((a[0] || "").toLowerCase() === "here") { g.levelChannel = null; save(); return ok(m, "level-ups will be sent in the channel where the member levels up"); }
  const ch = getChannel(m, a[0]);
  if (!ch) return usage(m, p, "levelchannel <#channel | here>");
  g.levelChannel = ch.id; save(); ok(m, `level-up messages will now be sent in ${ch}.`);
});
def("levelmessage", P.ManageGuild, async (m, a) => {
  const g = G(m.guild.id);
  if (!a.length) return info(m, `current: ${g.levelMessage}`);
  g.levelMessage = a[0].toLowerCase() === "reset" ? DEFAULTS().levelMessage : a.join(" ");
  save();
  const u = xpOf(g, m.author.id);
  const preview = g.levelMessage
    .replaceAll("{user}", `${m.author}`).replaceAll("{username}", m.author.username)
    .replaceAll("{level}", `${levelOf(u.total).level + 1}`).replaceAll("{xp}", `${u.total}`).replaceAll("{server}", m.guild.name);
  say(m, `level-up message set: preview:\n${preview.split("\n").map((l) => "> " + l).join("\n")}`);
});
def("levelreward", P.ManageGuild, async (m, a, p) => {
  const g = G(m.guild.id);
  const sub = (a[0] || "list").toLowerCase();
  if (sub === "add") {
    const lvl = parseInt(a[1], 10), role = getRole(m, a.slice(2).join(" "));
    if (!lvl || lvl < 1 || lvl > 1000 || !role) return usage(m, p, "levelreward add <level> <@role>");
    const me = m.guild.members.me;
    if (role.managed || (me && role.position >= me.roles.highest.position)) return err(m, "i can't give that role — it's managed or above my highest role");
    g.levelRewards[lvl] = role.id; save();
    let n = 0;
    for (const [uid, u] of Object.entries(g.xp)) {
      if (levelOf(u.total).level < lvl) continue;
      const mm = await m.guild.members.fetch(uid).catch(() => null);
      if (mm && !mm.roles.cache.has(role.id) && (await mm.roles.add(role).then(() => true).catch(() => false))) n++;
    }
    return ok(m, `level **${lvl}** → **${role.name}**${n ? ` • gave it to **${n}** member${n > 1 ? "s" : ""} already at that level` : ""}`);
  }
  if (sub === "remove") {
    const lvl = parseInt(a[1], 10);
    if (!g.levelRewards[lvl]) return err(m, "no reward at that level");
    delete g.levelRewards[lvl]; save(); return ok(m, `removed reward for level **${lvl}**`);
  }
  const rewards = Object.entries(g.levelRewards).sort((x, y) => x[0] - y[0]);
  if (!rewards.length) return say(m, `no level rewards set — add one with \`${p}levelreward add <level> <@role>\``);
  return say(m, rewards.map(([l, r]) => `level **${l}** → ${roleLabel(m, r)}`).join("\n"));
});
