def("addxp", P.ManageGuild, async (m, a, p) => {
  const mem = await getMember(m, a[0]);
  const amt = parseInt(a[1], 10);
  if (!mem || isNaN(amt)) return usage(m, p, "addxp <@user> <amount>");
  if (Math.abs(amt) > 10_000_000) return err(m, "that amount is too big (max 10,000,000)");
  const g = G(m.guild.id), u = xpOf(g, mem.id);
  u.total = Math.max(0, u.total + amt); save();
  const { level, into } = levelOf(u.total);
  await applyRewards(mem, g, level, true);
  ok(m, `${mem} is now **level ${level}** with ${into} xp.`);
});
def("setlevel", P.ManageGuild, async (m, a, p) => {
  const mem = await getMember(m, a[0]);
  const lvl = parseInt(a[1], 10);
  if (!mem || isNaN(lvl) || lvl < 0) return usage(m, p, "setlevel <@user> <level>");
  if (lvl > 1000) return err(m, "max level is 1000");
  const g = G(m.guild.id);
  xpOf(g, mem.id).total = cumulative(lvl); save();
  await applyRewards(mem, g, lvl, true);
  ok(m, `${mem} is now **level ${lvl}** with 0 xp.`);
});
def("resetxp", P.ManageGuild, async (m, a, p) => {
  const g = G(m.guild.id);
  if ((a[0] || "").toLowerCase() === "all") {
    for (const id of Object.keys(g.xp)) await applyRewards(m.guild.members.cache.get(id), g, 0, true);
    g.xp = {}; save(); return ok(m, "reset xp for the whole server");
  }
  const mem = await getMember(m, a[0]);
  if (!mem) return usage(m, p, "resetxp <@user | all>");
  delete g.xp[mem.id]; save();
  await applyRewards(mem, g, 0, true);
  ok(m, `reset xp for **${mem.user.username}**`);
});

// ---- safety
def("antiminor", P.Administrator, async (m, a, p) => {
  const g = G(m.guild.id), cfg = g.antiminor;
  if ((a[0] || "").toLowerCase() === "status" && a[1]) a = a.slice(1);
  const sub0 = (a[0] || "status").toLowerCase();
  const sub = { on: "enable", off: "disable", channel: "watch", media: "attach" }[sub0] || sub0;
  const U = "antiminor [status|enable|disable|log|modrole|watch|attach|test]";
  if (sub === "enable") {
    cfg.enabled = true; save();
    return ok(m, cfg.channels.length || cfg.mediaChannels.length ? "anti-minor **enabled**" : `anti-minor **enabled** — no channels yet, add one with ${p}antiminor watch #channel`);
  }
  if (sub === "disable") { cfg.enabled = false; save(); return ok(m, "anti-minor **disabled**"); }
  if (sub === "watch" || sub === "attach") {
    const key = sub === "watch" ? "channels" : "mediaChannels";
    const act = ["add", "remove"].includes((a[1] || "").toLowerCase()) ? a[1].toLowerCase() : null;
    const ch = getChannel(m, act ? a[2] : a[1]);
    if (!ch) return usage(m, p, `antiminor ${sub} [add|remove] <#channel>`);
    const has = cfg[key].includes(ch.id);
    const add = act ? act === "add" : !has;
    cfg[key] = add ? [...new Set([...cfg[key], ch.id])] : cfg[key].filter((x) => x !== ch.id);
    save();
    return ok(m, sub === "watch"
      ? `${add ? "now watching" : "stopped watching"} ${ch}`
      : `${ch} is ${add ? "now" : "no longer"} a **media-only** channel${add ? " (text-only messages get removed, captions are checked)" : ""}`);
  }
  if (sub === "log") {
    if ((a[1] || "").toLowerCase() === "off") { cfg.logChannel = null; save(); return ok(m, "log channel removed"); }
    const ch = getChannel(m, a[1]);
    if (!ch) return usage(m, p, "antiminor log <#channel|off>");
    const bad = checkChannel(m, ch, ["ViewChannel", "SendMessages", "EmbedLinks"]);
    if (bad) return err(m, bad);
    cfg.logChannel = ch.id; save(); return ok(m, `detections will be logged in ${ch}`);
  }
  if (sub === "modrole") {
    if ((a[1] || "").toLowerCase() === "off") { cfg.modRole = null; save(); return ok(m, "mod ping removed"); }
    const r = getRole(m, a.slice(1).join(" "));
    if (!r) return usage(m, p, "antiminor modrole <@role|off>");
    cfg.modRole = r.id; save(); return ok(m, `mod ping set to **${r.name}**`);
  }
  if (sub === "test") {
    const text = a.slice(1).join(" ");
    if (!text) return usage(m, p, "antiminor test <text>");
    const why = minorCheck(text);
    return why ? note(m, false, `would be **removed** — ${why}`, undefined, "FLAGGED", "bad") : note(m, true, "looks **clean**, it would not be flagged", undefined, "CLEAN", "good");
  }
  if (sub !== "status") return usage(m, p, U);
  const configured = !!(cfg.logChannel || cfg.modRole || cfg.channels.length || cfg.mediaChannels.length);
  const list = (arr) => arr.map((c) => chLabel(m, c)).join(", ") || "none";
  return sendCard(m, { eyebrow: "Anti-minor settings", ...stateOf(cfg.enabled, configured),
    footL: p + "antiminor", footR: cfg.enabled ? "active" : configured ? "paused" : "not set up", fields: [
    ["Log channel", cfg.logChannel ? chLabel(m, cfg.logChannel) : "not set"],
    ["Mod ping", cfg.modRole ? roleLabel(m, cfg.modRole) : "none"],
    ["Watched channels", list(cfg.channels)],
    ["Media-only channels", list(cfg.mediaChannels)],
  ] });
});

// ---- utility
// "56s", "5m 12s", "2h 3m", "1d 4h"
function afkFor(ms) {
  const s = Math.max(1, Math.floor(ms / 1000));
  const u = [["d", 86400], ["h", 3600], ["m", 60], ["s", 1]];
  const i = u.findIndex(([, n]) => s >= n);
  const [l, n] = u[i], a = Math.floor(s / n), nx = u[i + 1];
  const b = nx ? Math.floor((s % n) / nx[1]) : 0;
  return `${a}${l}` + (b ? ` ${b}${nx[0]}` : "");
}
