const studying = new Set();
def("study", P.Administrator, async (m, a, p) => {
  const gid = m.guild.id;
  if (studying.has(gid)) return err(m, "a study is already running here");
  const chans = []; let limit = 300, sample = false, useOcr = true;
  for (const t of a) {
    const low = t.toLowerCase();
    if (low === "sample") sample = true;
    else if (low === "noocr") useOcr = false;
    else if (/^\d+$/.test(t)) limit = Math.min(3000, Math.max(10, parseInt(t, 10)));
    else { const ch = getChannel(m, t); if (!ch) return err(m, `couldn't find ${t}`); chans.push(ch); }
  }
  if (!chans.length) { const lc = m.guild.channels.cache.get(G(gid).antiminor.logChannel); if (lc) chans.push(lc); }
  if (!chans.length) return usage(m, p, "study [#log-channel …] [limit] [sample] [noocr]");
  const me = m.guild.members.me;
  for (const ch of chans) if (!ch.isTextBased?.() || !ch.permissionsFor(me)?.has(["ViewChannel", "ReadMessageHistory"])) return err(m, `i need **View Channel** + **Read Message History** in ${ch}`);
  if (sample) limit = 25;
  studying.add(gid);
  const wait = await m.reply({ content: `reading ${sample ? "a sample of " : ""}${chans.map((c) => "#" + c.name).join(", ")}…`, allowedMentions: { parse: [], repliedUser: false } }).catch(() => null);
  const edit = (t) => wait?.edit({ content: t }).catch(() => {});
  let worker = null;
  try {
    // 1) collect log messages
    const msgs = [];
    for (const ch of chans) for (const x of await pullHistory(ch, limit)) {
      const fromBot = x.author?.bot || x.webhookId;
      const mine = x.author?.id === client.user.id && !x.embeds.some((e) => /minor detected/i.test(e.data?.title || "")) && !x.attachments.some((a) => a.name === "minor.png");
      if (fromBot && !mine) msgs.push(x);
    }
    // 2) extract
    const imgMsgs = msgs.filter((x) => msgImages(x).length).length;
    let ocrErr = "";
    if (useOcr && imgMsgs) { try { edit("starting OCR…"); worker = await makeOcr(edit); } catch (e) { worker = null; ocrErr = e.message; console.error("[study ocr init]", e.message); } }
    let ocrDone = 0, ocrSkipped = 0, ocrEmpty = 0, needOcr = false;
    const rows = [], userCache = new Map();
    const resolveUser = async (cands) => {
      for (const id of cands) {
        if (!userCache.has(id)) userCache.set(id, await client.users.fetch(id).catch(() => null));
        if (userCache.get(id)) return userCache.get(id);
      }
      return null;
    };
    for (const x of msgs) {
      const texts = msgTexts(x), urls = msgImages(x);
      const embedDesc = (x.embeds || []).map((e) => (e.data || e).description).find(Boolean) || "";
      let ocrText = "";
      const pre = parseLog(texts.join("\n"), embedDesc);
      // OCR whenever the text alone doesn't give us the flagged message or the verdict (the card image has them)
      if (urls.length && (pre.conf === "low" || !pre.verdict)) {
        if (!worker) needOcr = true;
        else if (ocrDone >= 200) ocrSkipped++;
        else {
          for (const u of urls) { try { ocrText += "\n" + await ocrUrl(worker, u); } catch (e) { ocrErr = e.message; console.error("[study ocr]", e.message); } }
          ocrDone++;
          if (!ocrText.trim()) ocrEmpty++;
          if (ocrDone % 10 === 0) edit(`reading cards… ${ocrDone}`);
        }
      }
      const raw = [...texts, ocrText].join("\n").trim();
      if (!raw) continue;
      const pr = parseLog(texts.join("\n"), embedDesc, ocrText);
      // user id: the card's own "ID …" first, then the <@user> in "<@user> banned by <@mod>". never the mod after "by".
      const modIds = new Set([...raw.matchAll(/\b(?:by|da)\s+<@!?(\d{17,20})>/gi)].map((q) => q[1]));
      const bannedId = /<@!?(\d{17,20})>\s*banned\s+by/i.exec(raw)?.[1];
      const ids = [...new Set([pr.card?.uid, bannedId, ...(raw.match(/\b\d{17,20}\b/g) || [])].filter(Boolean))]
        .filter((id) => !modIds.has(id) && ![x.id, x.channelId, gid, client.user.id].includes(id));
      const u = await resolveUser(ids);
      // "ignored by <@123>" -> readable mod name
      const mm = /^<@!?(\d{17,20})>$/.exec(pr.verdictBy || "");
      if (mm) { pr.verdictBy = x.guild?.members.cache.get(mm[1])?.displayName || (await resolveUser([mm[1]]))?.username || mm[1]; pr.logAction = pr.verdict + " by " + pr.verdictBy; }
      const ruleKey = (pr.rule || "").toLowerCase().replace(/\b\d+\b/g, "N").trim();
      rows.push({ at: x.createdTimestamp, msgId: x.id, channel: x.channel.name, uid: u?.id || ids[0] || "", name: u?.username || pr.card?.name || "", ...pr, ruleKey, ocr: !!ocrText.trim(), raw });
    }
    if (sample) {
      const lines = rows.slice(0, 3).map((r, i) => `#${i + 1} user=${r.uid || "?"} conf=${r.conf} rule="${clip(r.rule, 40)}" verdict="${r.verdict || "none"}${r.verdictBy ? " by " + r.verdictBy : ""}"\ntext="${clip(r.text, 150)}"\nraw="${clip(r.raw, 300)}"`);
      await wait?.delete().catch(() => {});
      return m.reply({ content: `**sample** — ${rows.length} usable of ${msgs.length} bot messages\nimages: ${imgMsgs} • OCR'd ${ocrDone} (${ocrEmpty} empty)${ocrErr ? `\n⚠ OCR error: ${clip(ocrErr, 150)}` : ""}${needOcr && !worker ? "\n⚠ image cards: run `npm i tesseract.js`" : ""}\n\`\`\`\n${lines.join("\n\n").slice(0, 1700).replace(/`/g, "'")}\n\`\`\``, allowedMentions: { parse: [], repliedUser: false } });
    }
    if (!rows.length) { await wait?.delete().catch(() => {}); return err(m, `no usable bot logs found — ${msgs.length} bot messages, ${imgMsgs} with images, ${ocrDone} OCR'd (${ocrEmpty} empty)${useOcr ? "" : " (noocr on)"}${ocrErr ? `\nOCR error: \`${clip(ocrErr, 150)}\`` : ""}${needOcr && !worker ? "\nrun `npm i tesseract.js` for OCR" : ""}`); }
    // 3) outcome = what the log message says (ban / ignore). The audit log is NOT used: on old cases it's wrong.
    //    current bans are only used to show the ban reason and to find bans the bot never flagged.
    edit("checking bans…");
    let bans = null;
    try { bans = await allBans(m.guild); } catch (e) { console.error("[study bans]", e.message); }
    for (const r of rows) {
      r.outcome = r.verdict || "pending"; // pending = nobody pressed ban/ignore on that card
      r.bannedBy = r.verdict === "banned" ? r.verdictBy : "";
      r.banReason = r.uid && bans?.has(r.uid) ? bans.get(r.uid) : "";
      r.laterBan = !!(r.uid && bans?.has(r.uid)); // user is banned on the server right now
    }
    // 4) replay the current regex
    for (const r of rows) { const dbg = {}; r.now = r.text && r.conf !== "low" ? (minorCheck(r.text, dbg) || "") : null; r.nowKind = dbg.kind || ""; }
    const cnt = (f) => rows.filter(f).length;
    // the same user/text gets flagged again and again (and ignored each time): count each (user, text) ONCE, a ban wins over an ignore
    const seen = new Map();
    for (const r of rows) {
      const k = (r.uid || r.name || r.msgId) + "|" + String(r.text).toLowerCase().replace(/\W+/g, "").slice(0, 40);
      const o = seen.get(k);
      if (!o || (r.outcome === "banned" && o.outcome !== "banned")) seen.set(k, r);
    }
    const uniq = [...seen.values()], merged = rows.length - uniq.length;
    const cntU = (f) => uniq.filter(f).length;
    const banned = cntU((r) => r.outcome === "banned"), ignored = cntU((r) => r.outcome === "ignored");
    // a flagged-but-ignored case is only a FALSE flag if mods mostly ignore that kind of match. if other mods BAN the same kind
    // (>=60% of everything this regex branch caught), the regex is valid and it's just mods disagreeing -> "disputed", never "fix"
    const kindStat = {};
    for (const r of uniq) if (r.now && (r.outcome === "banned" || r.outcome === "ignored")) { const k = (kindStat[r.nowKind || "?"] ||= { b: 0, i: 0 }); r.outcome === "banned" ? k.b++ : k.i++; }
    for (const r of uniq) { const k = kindStat[r.nowKind || "?"]; r.disputed = !!(r.now && r.outcome === "ignored" && k && k.b / (k.b + k.i) >= 0.6); }
    const stillFlags = uniq.filter((r) => r.outcome === "ignored" && r.now && !r.laterBan && !r.disputed);
    const disputedList = uniq.filter((r) => r.outcome === "ignored" && r.now && !r.laterBan && r.disputed);
    const ignoredButBanned = uniq.filter((r) => r.outcome === "ignored" && r.now && r.laterBan).length;
    const missed = uniq.filter((r) => r.outcome === "banned" && r.now === "");
    const testedB = cntU((r) => r.outcome === "banned" && r.now !== null), testedI = cntU((r) => r.outcome === "ignored" && r.now !== null);
    const stats = studyStats(uniq);
    const flaggedIds = new Set(rows.map((r) => r.uid));
    const manual = bans ? [...bans].filter(([id, rs]) => !flaggedIds.has(id) && STUDY_MINORISH.test(rs)) : [];
    // 5) files
    const head = ["date", "log_message_id", "channel", "user_id", "username", "flagged_text", "text_confidence", "rule", "log_says", "outcome", "ban_reason", "banned_by", "regex_now", "regex_via", "user_banned_now", "ocr", "raw"];
    const csv = "\ufeff" + [head.join(","), ...rows.map((r) => [new Date(r.at).toISOString(), r.msgId, r.channel, r.uid, r.name, r.text, r.conf, r.rule, r.logAction, r.outcome, r.banReason || "", r.bannedBy || "", r.now === null ? "n/a" : r.now || "clean", r.nowKind || "", r.laterBan ? "yes" : "no", r.ocr ? "yes" : "no", clip(r.raw, 600)].map(csvCell).join(","))].join("\n");
    const sec = (t, arr, f) => `== ${t} (${arr.length}) ==\n` + (arr.slice(0, 25).map(f).join("\n") || "none") + "\n";
    const cov = ruleCoverage(uniq), mods = modBias(uniq);
    const findings = [
      sec("FALSE FLAGS (fix): mods ignore this kind of match, the regex flags it", stillFlags, (r) => `- [${r.now}${r.nowKind ? " via " + r.nowKind : ""}] ${clip(r.text, 120)} — ${r.logAction || "ignored"}${r.rule ? " • other bot: " + clip(r.rule, 40) : ""}`),
      sec("DISPUTED (regex is VALID, keep it): ignored by one mod, banned by others for the same kind of match", disputedList, (r) => `- [${r.now} via ${r.nowKind}] ${clip(r.text, 100)} — ${r.logAction || "ignored"}`),
      `(+${ignoredButBanned} more ignored cases the regex flags, but that user is banned now: not counted)\n`,
      sec("BANNED by mods but this bot's regex MISSES (add these)", missed, (r) => `- ${clip(r.text, 140)}${r.rule ? " • other bot: " + clip(r.rule, 40) : ""}`),
      sec("RULE COVERAGE (other bot's rule -> is it in this bot?)", cov.slice(0, 25), (c) => `- ${clip(c.rule, 50)} — banned ${c.banned} (we catch ${c.caught}) • ignored ${c.ignored} (we flag ${c.falseFlag + c.laterBan}) • precision ${Math.round(c.prec * 100)}% => ${c.label}`),
      sec("MODS (low ban rate = their 'ignored' is weak evidence)", mods.slice(0, 15), (m) => `- ${m.mod}: banned ${m.banned}, ignored ${m.ignored}, ban rate ${Math.round(m.rate * 100)}%${m.rate < 0.2 ? "  <- ignores almost everything" : m.rate > 0.8 ? "  <- bans almost everything" : ""}`),
      sec("BANS with an age-like reason and NO detection in the logs (missed by the bot)", manual, ([id, rs]) => `- ${id}: ${clip(rs, 140)}`),
    ].join("\n");
    const files = [new AttachmentBuilder(Buffer.from(csv, "utf8"), { name: "study.csv" }), new AttachmentBuilder(Buffer.from(findings, "utf8"), { name: "findings.txt" })];
    await wait?.delete().catch(() => {});
    const w = stats.find((s) => s.ignored > 0);
    await sendCard(m, { eyebrow: "Study • minor logs", badge: "DONE", tone: "good", glow: true, footL: p + "study", footR: `${rows.length} cases`, blocks: [
      { label: "Scanned", value: `${msgs.length} log messages in ${chans.map((c) => "#" + c.name).join(" ")}` },
      { label: "Outcome (from log messages)", value: `banned ${banned} • ignored ${ignored} • undecided ${cnt((r) => r.outcome === "pending")}${merged ? ` (${merged} repeat flags merged)` : ""}` },
      { label: "Current regex vs history", value: `still flags ${stillFlags.length}/${testedI} ignored • misses ${missed.length}/${testedB} banned` },
      { label: "Weakest rule", value: w ? `${clip(w.rule, 40)} (${w.ignored} ignored, ${Math.round(w.precision * 100)}% precise)` : "none" },
    ] });
    const notes = [];
    if (needOcr && !worker) notes.push(`image cards can't be read: ${ocrErr ? "OCR error: " + clip(ocrErr, 120) : "add `tesseract.js` to package.json"}`);
    else if (ocrErr) notes.push("OCR error on some cards: " + clip(ocrErr, 120));
    if (ocrEmpty) notes.push(`${ocrEmpty} cards gave empty OCR text`);
    if (ocrSkipped) notes.push(`${ocrSkipped} cards skipped (OCR limit 200 per run)`);
    if (cnt((r) => r.outcome === "pending")) notes.push(`${cnt((r) => r.outcome === "pending")} cases have no ban/ignore verdict in the log message (still pending, or the card text wasn't readable) — excluded from the stats`);
    if (cnt((r) => r.conf === "low")) notes.push(`${cnt((r) => r.conf === "low")} rows had no readable flagged text (see raw column)`);
    await m.channel.send({ content: notes.length ? "⚠ " + notes.join("\n⚠ ") : undefined, files, allowedMentions: { parse: [] } }).catch(() => err(m, "i need the **attach files** permission here"));
  } catch (e) {
    console.error("[study]", e);
    await wait?.delete().catch(() => {});
    err(m, `study failed: \`${e.message}\``);
  } finally {
    studying.delete(gid);
    worker?.terminate?.().catch?.(() => {});
  }
});

// ---- booster
const isExempt = (member, cfg) => cfg.exemptRoles.some((r) => member.roles.cache.has(r));
const tpl = (t, member) => String(t).replaceAll("{user}", `<@${member.id}>`).replaceAll("{server}", member.guild.name);
const perksGuildOf = (_c, cfg) => (cfg.perksGuildId ? client.guilds.cache.get(cfg.perksGuildId) : null);

// a member started / stopped boosting
async function applyBoost(member, boosting) {
  const cfg = G(member.guild.id).booster;
  if (!cfg.enabled) return;
  const exempt = isExempt(member, cfg);
  if (cfg.roleId) {
    if (boosting) await member.roles.add(cfg.roleId).catch(() => {});
    else if (!exempt) await member.roles.remove(cfg.roleId).catch(() => {});
  }
  const pg = perksGuildOf(member.client, cfg);
  if (pg && cfg.perksRoleId) {
    const pm = await pg.members.fetch(member.id).catch(() => null);
    if (pm) {
      if (boosting) await pm.roles.add(cfg.perksRoleId).catch(() => {});
      else if (!exempt) await pm.roles.remove(cfg.perksRoleId).catch(() => {});
    }
  }
  const text = tpl(boosting ? cfg.boostMsg : cfg.unboostMsg, member);
  if (cfg.logChannel) member.guild.channels.cache.get(cfg.logChannel)?.send({ content: text, allowedMentions: { parse: [] } }).catch(() => {});
  if (cfg.dm) member.send(text.replace(/<@\d+>/g, member.user.username)).catch(() => {});
}
// give the roles to everybody who is boosting right now
async function syncBoosters(guild, cfg) {
  const members = await guild.members.fetch().catch(() => null);
  if (!members) return null;
  const pg = perksGuildOf(guild.client, cfg);
  const pms = pg && cfg.perksRoleId ? await pg.members.fetch().catch(() => null) : null;
  let role = 0, perks = 0;
  for (const mem of members.values()) {
    if (!mem.premiumSince) continue;
    if (cfg.roleId && !mem.roles.cache.has(cfg.roleId) && (await mem.roles.add(cfg.roleId).then(() => true).catch(() => false))) role++;
    const pm = pms?.get(mem.id);
    if (pm && !pm.roles.cache.has(cfg.perksRoleId) && (await pm.roles.add(cfg.perksRoleId).then(() => true).catch(() => false))) perks++;
  }
  return { role, perks };
}
// remove the roles from people who aren't boosting anymore (exempt roles are skipped)
async function sweepBoosters(guild, cfg) {
  const members = await guild.members.fetch().catch(() => null);
  if (!members) return null;
  let n = 0;
  if (cfg.roleId && members) {
    for (const mem of members.values()) {
      if (mem.roles.cache.has(cfg.roleId) && !mem.premiumSince && !isExempt(mem, cfg) && (await mem.roles.remove(cfg.roleId).then(() => true).catch(() => false))) n++;
    }
  }
  const pg = perksGuildOf(guild.client, cfg);
  if (pg && cfg.perksRoleId) {
    const pms = await pg.members.fetch().catch(() => null);
    for (const pm of pms?.values() ?? []) {
      if (!pm.roles.cache.has(cfg.perksRoleId)) continue;
      const hm = members?.get(pm.id);
      if (hm?.premiumSince || (hm && isExempt(hm, cfg))) continue;
      if (await pm.roles.remove(cfg.perksRoleId).then(() => true).catch(() => false)) n++;
    }
  }
  return n;
}
const plural = (n, w) => `${n} ${w}${n === 1 ? "" : "s"}`;

def("booster", P.Administrator, async (m, a, p) => {
  const cfg = G(m.guild.id).booster;
  if ((a[0] || "").toLowerCase() === "status" && a[1]) a = a.slice(1);
  const sub0 = (a[0] || "status").toLowerCase();
  const sub = { on: "enable", off: "disable" }[sub0] || sub0;
  const U = "booster [status|enable|disable|role|dm|boostmsg|unboostmsg|perks|access|log|exempt|sync|sweep]";
  const off = (x) => ["off", "none", "remove", "reset"].includes((x || "").toLowerCase());

  if (sub === "enable") {
    cfg.enabled = true; save();
    typing(m);
    if (!cfg.roleId && !cfg.perksGuildId) return ok(m, `booster automation **enabled**. set a role (${p}booster role) and/or cross-server perks (${p}booster perks <id>), then ${p}booster sync / ${p}booster sweep.`);
    const r = await syncBoosters(m.guild, cfg);
    if (!r) return ok(m, `booster automation **enabled**, but i couldn't load the member list — run ${p}booster sync again in a moment`);
    return ok(m, `booster automation **enabled**${r.role ? ` • gave the role to **${plural(r.role, "booster")}**` : ""}${r.perks ? ` • perks for **${plural(r.perks, "member")}**` : ""}`);
  }
  if (sub === "disable") { cfg.enabled = false; save(); return ok(m, "booster perks **disabled**"); }
  if (sub === "role") {
    if (off(a[1])) { cfg.roleId = null; cfg.enabled = cfg.enabled && !!cfg.perksGuildId; save(); return ok(m, cfg.enabled ? "booster role removed (cross-server perks still active)" : "booster role removed, automation **disabled**"); }
    const role = getRole(m, a.slice(1).join(" "));
    if (!role) return usage(m, p, "booster role <@role>");
    cfg.roleId = role.id; save();
    if (cfg.enabled) typing(m);
    const r = (cfg.enabled && (await syncBoosters(m.guild, cfg))) || { role: 0 };
    return ok(m, `booster role set to **${role.name}**${r.role ? ` • gave it to **${plural(r.role, "booster")}**` : ""}`);
  }
  if (sub === "dm") {
    const v = (a[1] || "").toLowerCase();
    cfg.dm = v === "on" ? true : v === "off" ? false : !cfg.dm; save();
    return ok(m, `boost DMs **${cfg.dm ? "on" : "off"}**`);
  }
  if (sub === "boostmsg" || sub === "unboostmsg") {
    const key = sub === "boostmsg" ? "boostMsg" : "unboostMsg";
    if (!a[1]) return info(m, `current: ${cfg[key]}\nvariables: {user} {server}`);
    cfg[key] = off(a[1]) && a.length === 2 ? DEFAULTS().booster[key] : a.slice(1).join(" ").slice(0, 500);
    save(); return ok(m, `${sub === "boostmsg" ? "boost" : "unboost"} message set: ${cfg[key]}`);
  }
  if (sub === "perks") {
    if (off(a[1])) { cfg.perksGuildId = null; cfg.perksRoleId = null; save(); return ok(m, "perks server removed"); }
    const pg = m.client.guilds.cache.get(idOf(a[1]));
    if (!pg) return err(m, "i'm not in that server — invite me there first, then use its id");
    cfg.perksGuildId = pg.id; cfg.perksRoleId = null; save();
    return ok(m, `perks server set to **${pg.name}** — now pick the role with ${p}booster access <role>`);
  }
  if (sub === "access") {
    const pg = perksGuildOf(m.client, cfg);
    if (!pg) return err(m, `set the perks server first: ${p}booster perks <server id>`);
    if (off(a[1])) { cfg.perksRoleId = null; save(); return ok(m, "perks access role removed"); }
    const q = a.slice(1).join(" ").replace(/^@/, "").trim().toLowerCase();
    const role = pg.roles.cache.get(idOf(a[1])) || pg.roles.cache.find((r) => r.name.toLowerCase() === q);
    if (!role) return err(m, `couldn't find that role in **${pg.name}** (use its id or exact name)`);
    cfg.perksRoleId = role.id; save();
    return ok(m, `perks access role set to **${role.name}** in **${pg.name}**`);
  }
  if (sub === "log") {
    if (off(a[1])) { cfg.logChannel = null; save(); return ok(m, "booster log removed"); }
    const ch = getChannel(m, a[1]);
    if (!ch) return usage(m, p, "booster log <#channel|off>");
    const bad = checkChannel(m, ch);
    if (bad) return err(m, bad);
    cfg.logChannel = ch.id; save(); return ok(m, `boosts will be logged in ${ch}`);
  }
  if (sub === "exempt") {
    const act = (a[1] || "").toLowerCase();
    const role = getRole(m, a.slice(2).join(" "));
    if (!["add", "remove"].includes(act) || !role) return usage(m, p, "booster exempt <add|remove> <@role>");
    cfg.exemptRoles = act === "add" ? [...new Set([...cfg.exemptRoles, role.id])] : cfg.exemptRoles.filter((x) => x !== role.id);
    save(); return ok(m, `**${role.name}** ${act === "add" ? "is now exempt from" : "is no longer exempt from"} perk removal`);
  }
  if (sub === "sync") {
    if (!cfg.roleId && !cfg.perksRoleId) return err(m, `nothing to sync — set a role (${p}booster role) or perks (${p}booster perks <id>) first`);
    typing(m);
    const r = await syncBoosters(m.guild, cfg);
    if (!r) return err(m, "couldn't load the member list (the server is big or discord is slow) — try again in a moment");
    return ok(m, `synced • role given to **${plural(r.role, "booster")}**${cfg.perksRoleId ? ` • perks given to **${plural(r.perks, "member")}**` : ""}`);
  }
  if (sub === "sweep") {
    typing(m);
    const n = await sweepBoosters(m.guild, cfg);
    if (n === null) return err(m, "couldn't load the member list (the server is big or discord is slow) — try again in a moment");
    return ok(m, `removed perks from **${plural(n, "member")}** who aren't boosting`);
  }
  if (sub !== "status") return usage(m, p, U);

  const pg = perksGuildOf(m.client, cfg);
  const configured = !!(cfg.roleId || cfg.perksGuildId || cfg.logChannel);
  return sendCard(m, { eyebrow: "Booster settings", ...stateOf(cfg.enabled, configured),
    footL: p + "booster", footR: `${m.guild.premiumSubscriptionCount ?? 0} boosting`, fields: [
    ["Booster role (here)", cfg.roleId ? roleLabel(m, cfg.roleId) : "not set"],
    ["Boost DM", cfg.dm ? "on" : "off"],
    ["Perks server", cfg.perksGuildId ? pg?.name ?? "unknown server" : "not set"],
    ["Perks access role", cfg.perksRoleId ? "@" + (pg?.roles.cache.get(cfg.perksRoleId)?.name ?? "unknown role") : "not set"],
    ["Booster log", cfg.logChannel ? chLabel(m, cfg.logChannel) : "not set"],
    ["Exempt roles (perks)", cfg.exemptRoles.length ? cfg.exemptRoles.map((r) => roleLabel(m, r)).join(", ") : "none"],
  ] });
});

// ---- bot profile (per server)
async function setBotProfile(m, field, value) {
  try {
    await client.rest.patch(Routes.guildMember(m.guild.id, "@me"), { body: { [field]: value } });
    return true;
  } catch (e) { err(m, `couldn't update (${e.message || "discord refused"})`); return false; }
}
async function attachmentDataUri(m, a) {
  const url = m.attachments.first()?.url || (/^https?:\/\//.test(a[0] || "") ? a[0] : null);
  if (!url) return null;
  const res = await fetch(url).catch(() => null);
  if (!res || !res.ok) return null;
  const type = res.headers.get("content-type") || "image/png";
  if (!/^image\/(png|jpe?g|gif|webp)/.test(type)) return null;
  return `data:${type.split(";")[0]};base64,${Buffer.from(await res.arrayBuffer()).toString("base64")}`;
}
for (const [cmd, field, label] of [["setbotpfp", "avatar", "avatar"], ["setbotbanner", "banner", "banner"]]) {
  def(cmd, P.ManageGuild, async (m, a, p) => {
    if ((a[0] || "").toLowerCase() === "remove") { if (await setBotProfile(m, field, null)) ok(m, `${label} removed for this server`); return; }
    const uri = await attachmentDataUri(m, a);
    if (!uri) return usage(m, p, `${cmd} [image | remove]`);
    if (await setBotProfile(m, field, uri)) ok(m, `${label} updated for this server`);
  });
}
def("setbotbio", P.ManageGuild, async (m, a, p) => {
  const text = a.join(" ");
  if (!text) return usage(m, p, "setbotbio [text | remove]");
  const remove = text.toLowerCase() === "remove";
  if (await setBotProfile(m, "bio", remove ? null : text.slice(0, 190))) ok(m, remove ? "bio removed for this server" : "bio updated for this server");
});

// ---- reload (config from disk)
def("reload", P.Administrator, async (m) => {
  try { const fresh = JSON.parse(fs.readFileSync(DB_PATH, "utf8")); fresh.guilds ||= {}; fresh.afk ||= {}; db = fresh; ok(m, "reloaded config from disk"); }
  catch (e) { err(m, `couldn't reload (${e.message})`); }
});

def("prefix", null, async (m, a, p) => {
  const g = G(m.guild.id);
  if (!a[0]) return say(m, `this server's prefix is \`${g.prefix}\``);
  if (!m.member.permissions.has(P.ManageGuild)) return say(m, "missing permissions");
  if (a[0].toLowerCase() === "reset") g.prefix = ",";
  else if (a[0].length > 5) return say(m, "prefix too long (max 5)");
  else g.prefix = a[0];
  save(); say(m, `prefix updated to \`${g.prefix}\`. @mentioning me still works too.`);
});
def("stickymessage", P.ManageMessages, async (m, a, p) => {
  const g = G(m.guild.id);
  const ch = getChannel(m, a[0]) || m.channel;
  const rest = (getChannel(m, a[0]) ? a.slice(1) : a).join(" ");
  if (!rest) return usage(m, p, "stickymessage [#channel] <text|off>");
  if (rest.toLowerCase() === "off") { delete g.sticky[ch.id]; save(); return ok(m, `sticky message removed from ${ch}`); }
  const sent = await ch.send(rest).catch(() => null);
  if (!sent) return err(m, "couldn't send in that channel");
  g.sticky[ch.id] = { content: rest, msgId: sent.id }; save();
  ok(m, `📌 sticky set. it'll stay at the bottom of ${ch.id === m.channel.id ? "this channel" : ch}.`);
});
def("synccategory", P.ManageChannels, async (m) => {
  const cat = m.channel.parent;
  if (!cat) return err(m, "this channel isn't in a category");
  let n = 0;
  for (const ch of cat.children.cache.values()) { if (await ch.lockPermissions().catch(() => null)) n++; }
  ok(m, `synced **${n}** channels with **${cat.name}**`);
});

